const ghRaw = $('GitHub - İçerik Kuyruğunu Çek').first().json;
const ghData = typeof ghRaw === 'string' ? JSON.parse(ghRaw) : (typeof ghRaw.data === 'string' ? JSON.parse(ghRaw.data) : ghRaw);
const posts = Array.isArray(ghData.posts) ? ghData.posts : [];

const liveItem = $('Canlı Kanal Geçmişini Kontrol Et').first()?.json || {};
const growthState = $input.first()?.json?.growthState || {};
const liveHtml = String(liveItem.data ?? liveItem.body ?? '');

const sd = $getWorkflowStaticData('global');
sd.startDate = sd.startDate || '2026-11-09';
if (!Array.isArray(sd.sentIds)) {
  sd.sentIds = [
    'tg_v2_d0_s1_ig_velocity',
    'tg_v2_d0_s2_tt_jail',
    'tg_v2_d0_s3_usa_geo',
    'tg_v2_d0_s4_safe_zone',
    'tg_v2_d0_s5_tt_auto',
    'tg_v2_d1_s1_profile_lurkers',
    'tg_v2_d1_s2_yt_watchtime',
    'tg_v2_d1_s3_bio_clarity',
    'tg_v2_d1_s4_tg_search'
  ];
}
if (!Array.isArray(sd.sentDigests)) sd.sentDigests = [];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];
if (!Array.isArray(sd.aiQueue)) sd.aiQueue = [];
sd.lastPublishedAt = Number(sd.lastPublishedAt || 0);
sd.lastRefillAt = Number(sd.lastRefillAt || 0);
sd.geminiDay = String(sd.geminiDay || '');
sd.geminiCountToday = Number(sd.geminiCountToday || 0);

const canonical = (text) => String(text || '')
  .toLowerCase()
  .replace(/https?:\/\/[^\s"'<>]+/g, (u) => u.split('?')[0])
  .replace(/\s+/g, ' ')
  .trim();

const simpleDigest = (text) => {
  const s = canonical(text);
  let h1 = 0x811c9dc5;
  let h2 = 0x9e3779b9;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (c + i), 0x85ebca6b) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + '_' + h2.toString(16).padStart(8, '0') + '_' + s.length;
};

// Auto-sync live channel posts from t.me/s/SocialoraOfficial so Termux handoff never double-posts
const sentIdSet = new Set(sd.sentIds);
const liveIdMatches = liveHtml.match(/\b(?:tg_v[0-9]+_[a-z0-9_]+|ai_[0-9]{4}_[0-9]+)\b/g) || [];
for (const lid of liveIdMatches) {
  if (!sentIdSet.has(lid)) {
    sentIdSet.add(lid);
    sd.sentIds.push(lid);
  }
}
const sentDigestSet = new Set(sd.sentDigests);

let latestLiveTs = 0;
const liveDateMatches = [...liveHtml.matchAll(/datetime="([^"]+)"/g)];
const todayLiveChannelSet = new Set();

const nowSec = Math.floor(Date.now() / 1000);
const trtNow = new Date((nowSec + 3 * 3600) * 1000);
const todayTrt = trtNow.toISOString().slice(0, 10);
if (sd.geminiDay !== todayTrt) {
  sd.geminiDay = todayTrt;
  sd.geminiCountToday = 0;
}

for (const m of liveDateMatches) {
  const ts = Math.floor(Date.parse(m[1]) / 1000);
  if (Number.isFinite(ts) && ts > 0) {
    if (ts > latestLiveTs) latestLiveTs = ts;
    const dStr = new Date((ts + 3 * 3600) * 1000).toISOString().slice(0, 10);
    if (dStr === todayTrt) todayLiveChannelSet.add(m[1]);
  }
}

const effectiveLastPub = Math.max(sd.lastPublishedAt, latestLiveTs);

const parseDue = (baseIso, dayOffset, hhmm) => {
  const [y, mo, da] = baseIso.split('-').map(Number);
  const [hh, mm] = String(hhmm).split(':').map(Number);
  return Math.floor(Date.UTC(y, mo - 1, da + Number(dayOffset || 0), hh - 3, mm, 0) / 1000);
};

// Merge GitHub scheduled posts + AI refilled queue
const allCandidates = [];
for (const p of posts) {
  if (!p || !p.id || !p.text || !p.time) continue;
  const due = parseDue(sd.startDate, p.day || 0, p.time);
  allCandidates.push({
    id: p.id,
    target: p.target === 'group' ? 'group' : 'channel',
    text: p.text,
    due,
    expires: due + 5400,
    source: 'github',
  });
}
for (const ap of sd.aiQueue) {
  if (!ap || !ap.id || !ap.text || !ap.due || ap.status !== 'pending') continue;
  allCandidates.push({
    id: ap.id,
    target: ap.target === 'group' ? 'group' : 'channel',
    text: ap.text,
    due: Number(ap.due),
    expires: Number(ap.expires || ap.due + 5400),
    source: 'ai',
  });
}

// Mark AI items older than 90m as expired
for (const ap of sd.aiQueue) {
  if (ap.status === 'pending' && Number(ap.expires || 0) < nowSec) {
    ap.status = 'expired';
  }
}

// Count today's sent per target (combine static history + live t.me today posts)
const trtMidnight = parseDue(todayTrt, 0, '00:00');
let sentTodayChannel = sd.sentHistory.filter((h) => h.target === 'channel' && Number(h.sentAt) >= trtMidnight).length;
sentTodayChannel = Math.max(sentTodayChannel, todayLiveChannelSet.size);
const sentTodayGroup = sd.sentHistory.filter((h) => h.target === 'group' && Number(h.sentAt) >= trtMidnight).length;

const unsentSorted = allCandidates
  .filter((c) => !sentIdSet.has(c.id) && !sentDigestSet.has(simpleDigest(c.text)) && c.expires >= nowSec)
  .sort((a, b) => a.due - b.due);

const spacingOk = !effectiveLastPub || (nowSec - effectiveLastPub >= 1800);
let picked = null;
for (const c of unsentSorted) {
  if (c.due > nowSec) continue;
  const targetCount = c.target === 'group' ? sentTodayGroup : sentTodayChannel;
  const targetCap = c.target === 'group' ? 1 : 5;
  if (targetCount >= targetCap) continue;
  if (!spacingOk) continue;
  picked = c;
  break;
}

if (picked) {
  return [{ json: { route: 'publish', nowSec, post: picked } }];
}

// Check if remaining upcoming queue needs AI refill (< 6 pending)
const futurePendingCount = unsentSorted.length;
const refillCooldownOk = !sd.lastRefillAt || (nowSec - sd.lastRefillAt >= 21600);
if (futurePendingCount < 6 && refillCooldownOk && sd.geminiCountToday < 40) {
  const maxDue = Math.max(nowSec, ...allCandidates.map((c) => c.due));
  const nextDate = new Date((maxDue + 3 * 3600 + 86400) * 1000);
  const baseDateIso = nextDate.toISOString().slice(0, 10);
  const mmdd = baseDateIso.slice(5, 7) + baseDateIso.slice(8, 10);
  const dayOfYear = Math.floor((nextDate - new Date(Date.UTC(nextDate.getUTCFullYear(), 0, 0))) / 86400000);

  const AI_TOPICS = [
    ["FORMAT:cheatsheet (NO WEBSITE URL — end with Forward-to-a-friend CTA) | 3 copy-paste 2-second Reel opening hooks that beat swipe-away", "", "channel"],
    ["FORMAT:tool | TikTok 200-view jail & 3-second retention hook math", "https://www.getsocialora.com/tools/tiktok-shadowban-checker", "channel"],
    ["FORMAT:clinic (pull readers into @SocialoraChat) | Live Hook Teardown: drop your last video retention & niche in @SocialoraChat", "", "channel"],
    ["FORMAT:mythbuster | How Instagram Explore tests fresh Reels vs silent profile visitors", "https://www.getsocialora.com/tools/instagram-shadowban-checker", "channel"],
    ["FORMAT:cheatsheet (NO WEBSITE URL — saveable checklist) | Pre-upload 4-point Reel & TikTok export checklist", "", "channel"],
    ["FORMAT:tool | Pricing Instagram Reels brand deals & UGC usage rights cleanly", "https://www.getsocialora.com/tools/instagram-sponsorship-rate-calculator", "channel"],
    ["FORMAT:service (max 15% promo ratio) | How Instagram Auto Likes & Reels Views build early social proof on fresh uploads", "https://www.getsocialora.com/instagram", "channel"],
    ["FORMAT:tool | Why subtitles in the bottom 25% kill short-form watch time", "https://www.getsocialora.com/tools/reels-tiktok-safe-zone-guide", "channel"],
    ["FORMAT:clinic (pull readers into @SocialoraChat) | Where do your profile visitors drop off before following? Let's diagnose in @SocialoraChat", "https://t.me/SocialoraChat", "channel"],
    ["FORMAT:tool | Telegram channel search ranking & niche CPM benchmarks", "https://www.getsocialora.com/tools/telegram-channel-money-calculator", "channel"]
  ];
  const slots = ["09:40", "13:15", "16:30", "19:25", "22:05"];
  const batchItems = [];
  for (let i = 0; i < 5; i++) {
    const [topic, url, target] = AI_TOPICS[(dayOfYear * 2 + i) % AI_TOPICS.length];
    const id = 'ai_' + mmdd + '_' + (i + 1);
    if (sentIdSet.has(id) || sd.aiQueue.some((q) => q.id === id)) continue;
    const trackedUrl = url && url.includes('getsocialora.com') ? (url + '?utm_source=telegram&utm_medium=' + target + '&utm_campaign=' + id) : url;
    const due = parseDue(baseDateIso, 0, slots[i]);
    batchItems.push({ idx: i, id, target, topic, trackedUrl, time: slots[i], due, expires: due + 5400 });
  }
  if (batchItems.length > 0) {
    sd.lastRefillAt = nowSec;
    sd.geminiCountToday += 1;
    const specLines = batchItems.map((b, idx) => (idx + 1) + '. id=' + b.id + ' | target=' + b.target + ' | topic=' + b.topic + ' | url=' + (b.trackedUrl || 'NONE_DO_NOT_ADD_LINK')).join('\n');
    const winSummary = Array.isArray(growthState.winningFormats) && growthState.winningFormats.length ? JSON.stringify(growthState.winningFormats) : 'No history yet';
    return [{ json: { route: 'refill', nowSec, baseDateIso, batchItems, specLines, winSummary } }];
  }
}

return [];

const { post, nowSec } = $input.first()?.json || {};
const text = String(post?.text || '').trim();
if (text.length < 30 || text.length > 3500) {
  throw new Error('İçerik uzunluğu sınır dışında (' + text.length + ').');
}
if (/\b\d{5,}:[A-Za-z0-9_-]{20,}/.test(text) || /\b(?:100% safe|never drops|guaranteed followers|skyrocket|unleash|game[- ]changer|unlock your potential|let'?s dive in|in today'?s digital)\b/i.test(text) || /(?:\bsonuç olarak\b|\bunutmayın\b|\bkapsamlı\b|\bin conclusion\b)/i.test(text)) {
  throw new Error('İçerikte yasak/robotik kalıp veya gizli bilgi bulundu.');
}

const escHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = (s) => escHtml(s).replace(/"/g, '&quot;');
const parseSafeHttpsUrl = (rawStr) => {
  if (!/^https:\/\//i.test(rawStr)) return null;
  const rest = rawStr.slice(8);
  const cut = rest.search(/[/?#]/);
  const auth = cut === -1 ? rest : rest.slice(0, cut);
  if (!auth || auth.includes('..') || !/^[a-z0-9.-]+$/i.test(auth)) return null;
  const host = auth.toLowerCase();
  const tailAll = cut === -1 ? '' : rest.slice(cut);
  const hIdx = tailAll.indexOf('#');
  const noHash = hIdx === -1 ? tailAll : tailAll.slice(0, hIdx);
  const hash = hIdx === -1 ? '' : tailAll.slice(hIdx);
  const qIdx = noHash.indexOf('?');
  const pathRaw = qIdx === -1 ? noHash : noHash.slice(0, qIdx);
  const searchRaw = qIdx === -1 ? '' : noHash.slice(qIdx + 1);
  const pathname = pathRaw ? (pathRaw.startsWith('/') ? pathRaw : '/' + pathRaw) : '/';
  return { host, pathname, searchRaw, hash };
};
const buildSocialoraUrl = (parsed, utms) => {
  const pairs = [];
  const seen = new Set();
  if (parsed.searchRaw) {
    for (const part of parsed.searchRaw.split('&')) {
      if (!part) continue;
      const eq = part.indexOf('=');
      const k = eq === -1 ? part : part.slice(0, eq);
      const v = eq === -1 ? '' : part.slice(eq + 1);
      if (Object.prototype.hasOwnProperty.call(utms, k)) {
        if (!seen.has(k)) {
          pairs.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(utms[k])));
          seen.add(k);
        }
      } else {
        pairs.push(part);
      }
    }
  }
  for (const [k, val] of Object.entries(utms)) {
    if (!seen.has(k)) pairs.push(encodeURIComponent(k) + '=' + encodeURIComponent(String(val)));
  }
  return 'https://www.getsocialora.com' + parsed.pathname + (pairs.length ? '?' + pairs.join('&') : '') + parsed.hash;
};

let out = '';
let last = 0;
const urlRe = /https?:\/\/[^\s]+/g;
let m;
while ((m = urlRe.exec(text)) !== null) {
  out += escHtml(text.slice(last, m.index));
  const raw = m[0].replace(/[.,!?)]+$/, '');
  const tail = m[0].slice(raw.length);
  const u = parseSafeHttpsUrl(raw);
  if (!u) {
    throw new Error('Bağlantı doğrulama hatası: Güvensiz veya geçersiz URL: ' + raw);
  }
  if (u.host === 'www.getsocialora.com' || u.host === 'getsocialora.com') {
    const finalUrl = buildSocialoraUrl(u, {
      utm_source: 'telegram',
      utm_medium: post.target,
      utm_campaign: post.id,
    });
    const cleanPath = u.pathname.replace(/\/+$/, '');
    const label = 'getsocialora.com' + cleanPath;
    out += '<a href="' + escAttr(finalUrl) + '">' + escHtml(label) + '</a>' + escHtml(tail);
  } else if (u.host === 't.me' && ['/SocialoraOfficial', '/SocialoraChat'].includes(u.pathname) && !u.searchRaw) {
    out += escHtml(m[0]);
  } else {
    throw new Error('Bağlantı doğrulama hatası: Beklenmeyen dış bağlantı: ' + raw);
  }
  last = m.index + m[0].length;
}
out += escHtml(text.slice(last));

return [{
  json: {
    post,
    nowSec,
    chatId: post.target === 'group' ? '@SocialoraChat' : '@SocialoraOfficial',
    htmlText: out,
  }
}];

const src = $('HTML Link & Güvenlik Filtresi').first().json;
const tgRes = $input.first().json;
const sd = $getWorkflowStaticData('global');

const post = src.post;
const nowSec = Math.floor(Date.now() / 1000);
const msgId = tgRes?.result?.message_id ?? tgRes?.message_id ?? null;

const canonical = (text) => String(text || '')
  .toLowerCase()
  .replace(/https?:\/\/[^\s"'<>]+/g, (u) => u.split('?')[0])
  .replace(/\s+/g, ' ')
  .trim();

const simpleDigest = (text) => {
  const s = canonical(text);
  let h1 = 0x811c9dc5;
  let h2 = 0x9e3779b9;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (c + i), 0x85ebca6b) >>> 0;
  }
  return h1.toString(16).padStart(8, '0') + '_' + h2.toString(16).padStart(8, '0') + '_' + s.length;
};

if (!Array.isArray(sd.sentIds)) sd.sentIds = [];
if (!Array.isArray(sd.sentDigests)) sd.sentDigests = [];
if (!Array.isArray(sd.sentHistory)) sd.sentHistory = [];

if (!sd.sentIds.includes(post.id)) sd.sentIds.push(post.id);
const dig = simpleDigest(post.text);
if (!sd.sentDigests.includes(dig)) sd.sentDigests.push(dig);
if (sd.sentDigests.length > 400) sd.sentDigests = sd.sentDigests.slice(-400);

sd.sentHistory.push({ id: post.id, target: post.target, messageId: msgId, sentAt: nowSec });
if (sd.sentHistory.length > 200) sd.sentHistory = sd.sentHistory.slice(-200);
sd.lastPublishedAt = nowSec;

if (Array.isArray(sd.aiQueue)) {
  for (const item of sd.aiQueue) {
    if (item.id === post.id) {
      item.status = 'sent';
      item.messageId = msgId;
      item.sentAt = nowSec;
    }
  }
}

return [{ json: { status: 'published', id: post.id, target: post.target, message_id: msgId, sentAt: nowSec } }];

const ctx = $('Takvim, Kuyruk & Tekrar Kontrolü').first().json;
const gRes = $input.first().json;
const rawText = String(gRes?.mergedResponse ?? gRes?.content?.parts?.[0]?.text ?? '');
const cleaned = rawText.trim().replace(new RegExp('^\\x60{3}(?:json)?\\s*|\\s*\\x60{3}$', 'gi'), '');

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch {
  return [{ json: { added: 0, reason: 'invalid_json' } }];
}
const arr = Array.isArray(parsed) ? parsed : (Array.isArray(parsed?.posts) ? parsed.posts : []);
if (!arr.length) return [{ json: { added: 0, reason: 'empty_array' } }];

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.aiQueue)) sd.aiQueue = [];
if (!Array.isArray(sd.sentIds)) sd.sentIds = [];

const byId = new Map();
for (const x of arr) {
  if (x && typeof x.id === 'string' && typeof x.text === 'string') {
    byId.set(x.id.trim(), x.text.trim());
  }
}

const bannedRe = /\b(?:100% safe|never drops|guaranteed followers|skyrocket|unleash|game[- ]changer|unlock your potential|let'?s dive in|in today'?s digital)\b|\b\d{5,}:[A-Za-z0-9_-]{20,}/i;
let added = 0;
for (const b of (ctx.batchItems || [])) {
  let text = byId.get(b.id) || '';
  if (!text) continue;
  if (b.trackedUrl && !text.includes(b.trackedUrl)) {
    text = text + '\n\n' + b.trackedUrl;
  }
  if (text.length < 180 || text.length > 900 || bannedRe.test(text)) continue;
  if (sd.sentIds.includes(b.id) || sd.aiQueue.some((q) => q.id === b.id)) continue;
  sd.aiQueue.push({
    id: b.id,
    target: b.target,
    text,
    due: b.due,
    expires: b.expires,
    status: 'pending',
  });
  added += 1;
}

if (sd.aiQueue.length > 60) {
  sd.aiQueue = sd.aiQueue.slice(-60);
}

return [{ json: { added, baseDateIso: ctx.baseDateIso, totalQueue: sd.aiQueue.length } }];
